'use strict';
const $=s=>document.querySelector(s), key='ls-moldworks-projects-v1';
let projects=[];try{const v=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(v))projects=v;}catch{}
projects.forEach(p=>{if(!p.issuer)p.issuer={};});
let current=null,view='home',statusFilter='all',customerFilter='all',dateFilter='all';
const statuses=Workflow.labels;
const statusOf=p=>Object.hasOwn(statuses,p.status)?p.status:'draft';
const statusOptions=p=>Object.entries(statuses).map(([v,t])=>`<option value="${v}" ${statusOf(p)===v?'selected':''}>${t}</option>`).join('');
const thumbnail=p=>/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(p.thumbnail||'')?`<img class="part-thumb" src="${p.thumbnail}" alt="${esc(p.part)} ön izlemesi">`:'<span class="part-thumb placeholder" aria-label="Görsel eklenmedi">◇</span>';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>new Date(v).toLocaleDateString('tr-TR');
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function persist(){try{localStorage.setItem(key,JSON.stringify(projects));window.dispatchEvent(new Event('ls-data-saved'));return true;}catch{toast('Kayıt yapılamadı. Tarayıcı depolama alanını kontrol edin.');return false;}}
function hideSplash(){$('#splash').style.opacity='0';setTimeout(()=>$('#splash').remove(),500);}
$('#skip').onclick=hideSplash;setTimeout(()=>{if($('#splash'))hideSplash();},2800);
function heading(title,sub,action=true){return `<div class="heading"><div><span class="eyebrow">LS MOLDWORKS / TEKLİF YÖNETİMİ</span><h1>${title}</h1><p>${sub}</p></div>${action?'<button class="primary new-project">＋ Yeni Teklif</button>':''}</div>`;}
function rows(query=''){const q=query.toLocaleLowerCase('tr');return projects.filter(p=>dateFilter==='all'||QuoteDates.classify(p)[dateFilter]).filter(p=>customerFilter==='all'||p.customerId===customerFilter).filter(p=>statusFilter==='all'||statusOf(p)===statusFilter).filter(p=>[p.code,p.customer,p.part,p.created].join(' ').toLocaleLowerCase('tr').includes(q)).sort((a,b)=>(b.updatedAt||b.created).localeCompare(a.updatedAt||a.created)).map(p=>`<tr><td><strong>${esc(p.code)}</strong><small>${p.revision?'Revizyon '+p.revision:'İlk sürüm'}</small></td><td><strong>${esc(p.customer)}</strong></td><td><div class="part-cell">${thumbnail(p)}<span>${esc(p.part)}</span></div></td><td>${p.alternatives.map(a=>esc(a.cavities)+' göz').join(' / ')}</td><td><span>Son işlem: ${date(p.updatedAt||p.created)}</span><small>Dönüş: ${QuoteDates.format(p.responseDue)}<br>Geçerlilik: ${QuoteDates.format(QuoteDates.validUntil(p))}</small>${dateBadge(p)}</td><td><span class="badge status-${statusOf(p)}">${statuses[statusOf(p)]}</span></td><td><div class="quick-actions"><button class="open secondary" data-id="${esc(p.id)}">Aç ↗</button><details class="quick-menu"><summary aria-label="${esc(p.code)} hızlı işlemler">•••</summary><div><button data-quick="revision" data-id="${esc(p.id)}">Revizyon oluştur</button><button data-quick="copy" data-id="${esc(p.id)}">Kopyala</button><button data-quick="pdf" data-id="${esc(p.id)}">PDF ön izleme</button></div></details></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Teklif bulunamadı. Yeni teklif oluşturarak başlayın.</td></tr>';}
function table(){return `<section class="panel"><div class="panel-head"><div><h3>${view==='home'?'Son Teklifler':view==='approvals'?'İncelenecek Teklifler':'Teklif Arşivi'}</h3><p style="margin:6px 0 0;font-size:11px">Müşteri, teklif kodu veya parça adıyla kayıtlarınıza ulaşın.</p></div>${view==='home'?'':'<input id="search" class="search" aria-label="Eski tekliflerde ara" placeholder="Teklif kodu, müşteri veya parça adıyla ara…">'}</div><div class="archive-customer-filter"><label for="archive-customer">Müşteriye göre arşiv</label><select id="archive-customer"><option value="all">Tüm firmalar</option>${Customers.all().map(c=>`<option value="${c.id}" ${customerFilter===c.id?'selected':''}>${esc(c.name)} (${esc(c.prefix)})</option>`).join('')}</select></div>${dateFiltersHtml()}<div class="status-filters" aria-label="Teklif durumu filtresi">${filterButtons()}</div><div class="table-wrap"><table><thead><tr><th>TEKLİF KODU</th><th>MÜŞTERİ</th><th>PARÇA ADI</th><th>ALTERNATİFLER</th><th>TARİHLER</th><th>DURUM</th><th></th></tr></thead><tbody id="rows">${rows()}</tbody></table></div></section>`;}
function renderHome(next='home'){
 view=next;current=null;
 $('#breadcrumb').textContent=view==='home'?'Genel Bakış':view==='approvals'?'Teklif Onay Kutusu':'Teklif Arşivi';
 document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));
 $('#content').innerHTML=heading(view==='home'?'Genel Bakış':view==='approvals'?'Teklif Onay Kutusu':'Teklif Arşivi',view==='home'?'Tekliflerinize ulaşın, kaldığınız yerden devam edin.':'Projelerinizi ve geçmiş revizyonları inceleyin.')+(view==='home'?`
 <section class="dashboard-search"><label for="search">TEKLİFLERİNİZDE ARAYIN</label><div class="search-line"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="Eski tekliflerde ara" placeholder="Teklif kodu, müşteri veya parça adıyla ara…"></div></section>
 ${deadlineCards()}<div class="overview-row"><div class="stats status-stats">${Object.entries(statuses).map(([v,t])=>`<button class="stat status-card" data-filter="${v}" aria-pressed="${statusFilter===v}"><span>${t}</span><strong>${projects.filter(p=>statusOf(p)===v).length}<small>kayıt</small></strong></button>`).join('')}</div><div class="mini-mold"><div><span class="eyebrow">LS MOLDWORKS</span><p>Her detayda<br>mühendislik.</p></div><div class="mold" aria-hidden="true"><div class="plate"></div><div class="plate"></div></div><button id="motion-toggle" class="motion-toggle" aria-pressed="false" aria-label="Kalıp animasyonunu duraklat">Ⅱ</button></div></div>`:'')+table()+`<div class="guide"><b>◇</b><div><h3>Yerel çalışma alanı</h3><p>Kayıtlar bu tarayıcıda saklanır. Malzeme ön hesabı kullanılabilir; STEP geometrik araması ve malzeme hesabı kullanılabilir; tam kalıp tasarımı / OCR henüz bağlı değildir.</p></div></div>`;
 bindNew();$('#search').oninput=e=>{$('#rows').innerHTML=rows(e.target.value);bindOpen();};bindOpen();bindFilters();bindDateFilters();$('#archive-customer').onchange=e=>{customerFilter=e.target.value;$('#rows').innerHTML=rows($('#search').value);bindOpen();};
 if($('#motion-toggle'))$('#motion-toggle').onclick=e=>{const b=e.currentTarget,paused=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(paused));b.setAttribute('aria-label',paused?'Kalıp animasyonunu oynat':'Kalıp animasyonunu duraklat');b.textContent=paused?'▷':'Ⅱ';b.closest('.mini-mold').classList.toggle('paused',paused);};
}

function bindNew(){document.querySelectorAll('.new-project').forEach(b=>b.onclick=()=>{populateCustomers();$('#project-dialog').showModal();});}
function bindOpen(){document.querySelectorAll('.open').forEach(b=>b.onclick=()=>openProject(b.dataset.id));document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>quickAction(b.dataset.id,b.dataset.quick));}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{if(b.dataset.view==='approvals'){statusFilter='pending';customerFilter='all';dateFilter='all';renderHome('approvals');}else if(b.dataset.view==='customers'){current=null;view='customers';Customers.render(projects,id=>{customerFilter=id;statusFilter='all';renderHome('quotes');});}else if(b.dataset.view==='backup'){current=null;view='backup';renderBackup();}else if(b.dataset.view==='settings'){current=null;view='settings';Settings.render();}else renderHome(b.dataset.view);});$('#close-dialog').onclick=()=>$('#project-dialog').close();
$('#project-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),prefix=f.get('prefix').trim().toUpperCase(),year=String(new Date().getFullYear()).slice(-2);const base=prefix+year;const num=Math.max(0,...projects.filter(p=>p.base?.startsWith(base)&&p.prefix===prefix&&p.year===year).map(p=>Number(p.base.slice(base.length))||0))+1;if(num>999){toast('Bu müşteri için yıllık 999 teklif sınırına ulaşıldı.');return;}const code=base+String(num).padStart(3,'0');let customer=Customers.get($('#customer-select').value);if(!customer){const name=f.get('customer').trim();customer=Customers.all().find(c=>c.name.toLocaleLowerCase('tr')===name.toLocaleLowerCase('tr')&&c.prefix===prefix);if(!customer)try{customer=Customers.upsert({id:crypto.randomUUID(),name,prefix,contact:'',email:'',phone:'',address:'',language:'tr'});}catch(error){toast(error.message);return;}}const p={id:crypto.randomUUID(),code,base:code,prefix,year,customerId:customer.id,customerInfo:structuredClone(customer),customer:customer.name,part:f.get('part').trim(),request:f.get('request').trim(),quoteDate:QuoteDates.today(),responseDue:'',issuer:Settings.get(),terms:Settings.get().terms||{},created:new Date().toISOString(),revision:0,files:[],language:customer.language||'tr',alternatives:[alternative(2),alternative(4)]};projects.push(p);if(!persist()){projects.pop();return;}$('#project-dialog').close();e.target.reset();openProject(p.id);};
function alternative(cavities){const rules=Settings.get();return {costProfile:{...structuredClone(rules.costProfile||Costing.defaults),snapshotAt:new Date().toISOString()},pricing:{...Costing.defaults,...rules.costProfile,mode:'manual',trimEnabled:false},costLines:[],material:{...materialDefaults,edge:rules.edge,threshold:rules.threshold,growth:rules.growth},id:crypto.randomUUID(),cavities,core:'none',slide:'none',length:'',width:'',height:'',coreSize:'',cost:''};}
function openProject(id){current=projects.find(p=>p.id===id);if(!current)return;if(current.status==='approved'&&!Workflow.approved(current))Workflow.invalidate(current);$('#breadcrumb').textContent=current.code;$('#content').innerHTML=heading(esc(current.code),esc(current.customer)+' · '+esc(current.part),false)+`<div class="actions"><button id="back" class="secondary">← Arşive dön</button><button id="revision" class="secondary">Yeni revizyon oluştur</button><span class="badge" id="workflow-status">${statuses[statusOf(current)]}</span><button id="apply-company" class="secondary">Güncel firma bilgilerini uygula</button><button id="save" class="primary">Değişiklikleri kaydet</button></div>${workflowHtml(current)}${datesHtml(current)}<div class="steps"><span class="step active">01 · Proje ve Belgeler</span><span class="step">02 · Kalıp Alternatifleri</span><span class="step">03 · İnceleme ve Çıktı</span></div><div class="notice">Arayüz prototipi: STEP ve IGES katıları analiz edilir. Belgelerden talep ve ölçü adayları çıkarılıp aşağıda incelemeye sunulur. Parasolid/CATIA analizi lisanslı çevirici gerektirir. Dosya adları, orijinalleri ve içerik parmak izleri kaydedilir; 2D ölçü adayları onayla, 3D taslak ölçüleri incelemeyle hesaba aktarılır. Malzeme bölümünde girilen ölçülerden blok ağırlığı ve bedeli hesaplanır; otomatik kalıp tasarımı / geometrik eşitlik doğrulaması yapılmaz.</div><section class="panel"><div class="panel-head"><h3>01 / Proje belgeleri</h3><span class="badge">2D veya 3D yeterli</span></div><div class="body-pad"><div class="dropzone"><label>◇  Teknik resim, model veya müşteri talebi ekleyin<input id="files" type="file" multiple accept=".pdf,.step,.stp,.x_t,.x_b,.igs,.iges,.catpart,.catproduct,.dwg,.dxf,.png,.jpg,.jpeg,.eml,.txt"></label><small>PDF · STEP · Parasolid · CATIA · IGES · DWG/DXF · Görsel · E-posta<br>Format listesi hedeflenen desteği gösterir; orijinal dosyalar saklanır; Belge analizi aşağıdaki panelden başlatılır; özel CAD biçimleri için çevirici gerekir.</small></div><div id="file-list" class="files">${fileList()}</div><div class="package-actions"><button id="download-package" class="secondary">Teklif dosya paketini indir · ZIP</button><small id="package-status" role="status">Orijinal dosyalar tarayıcı dosya deposunda ve seçili kayıt klasöründe saklanır.</small></div><section id="document-intake"></section><section id="model-matches" class="model-matches"></section><div class="thumbnail-editor"><div id="thumbnail-current">${thumbnail(current)}</div><label>Parça ön izleme görseli<input id="thumbnail-file" type="file" accept="image/png,image/jpeg,image/webp"><small>Elle görsel ekleyin · PNG/JPG/WebP · en fazla 5 MB. 3D inceleme görünüşü teklif görseli olarak kaydedilebilir.</small></label><button id="thumbnail-remove" class="secondary">Görseli kaldır</button></div><label>Müşteri talebi / teknik notlar<textarea id="request" rows="3">${esc(current.request)}</textarea></label></div></section><section class="panel"><div class="panel-head"><div><h3>02 / Kalıp alternatifleri</h3><p style="font-size:12px;margin-bottom:0">Her alternatifin kapsamı, ölçüleri ve tutarı bağımsızdır.</p></div><button id="add-alt" class="secondary">＋ Alternatif ekle</button></div><div class="body-pad"><div id="alternatives" class="alternatives">${current.alternatives.map(altHtml).join('')}</div></div></section><section class="panel body-pad" id="quote-terms"><h2>Teklif koşulları</h2><p>Bu teklife özel düzenleyebilirsiniz.</p>${Settings.termsFields(current.terms||{})}<button type="button" id="apply-terms" class="secondary">Firma varsayılanlarını bu teklife uygula</button></section><section class="panel"><div class="panel-head"><h3>03 / Teklif ön izleme</h3></div><div class="body-pad"><div class="inline"><label for="language">Çıktı dili</label><select id="language"><option value="tr">Türkçe</option><option value="en">English</option></select><button class="primary" id="preview">Ön izleme oluştur</button></div><label class="toggle" style="max-width:330px">Parça inceleme bölümünü dahil et<input id="include-analysis" type="checkbox" checked></label><label>Kısa parça incelemesi (seçilen çıktı dilinde)<textarea id="analysis" rows="3" placeholder="Teknik değerlendirme ve teklif varsayımlarını yazın.">${esc(current.analysis||'')}</textarea></label></div></section><div id="readiness" role="status"></div><div id="output"></div>`;$('#language').value=current.language;$('#back').onclick=()=>renderHome('quotes');$('#save').onclick=()=>{capture();if(persist())toast('Proje kaydedildi.');};$('#files').onchange=addProjectFiles;bindFileActions();$('#download-package').onclick=()=>downloadProjectPackage().catch(error=>{$('#package-status').textContent=error.message;});$('#add-alt').onclick=()=>{capture();markEdited();current.alternatives.push(alternative(1));$('#alternatives').innerHTML=current.alternatives.map(altHtml).join('');bindAlternatives();$('#output').innerHTML='';};$('#revision').onclick=()=>{capture();if(persist())quickAction(current.id,'revision');};$('#thumbnail-file').onchange=uploadThumbnail;$('#thumbnail-remove').onclick=()=>{markEdited();current.thumbnail='';$('#thumbnail-current').innerHTML=thumbnail(current);$('#output').innerHTML='';};$('#apply-company').onclick=()=>{capture();current.issuer=Settings.get();markEdited();if(persist())toast('Güncel firma kimliği bu teklife uygulandı.');};$('#apply-terms').onclick=()=>{markEdited();current.terms=Settings.get().terms||{};for(const k of QuoteTools.termKeys)document.querySelector(`[name="term-${k}"]`).value=current.terms[k]||'';$('#output').innerHTML='';};$('#preview').onclick=()=>preview();renderModelMatches();bindDocumentIntake();bindAlternatives();bindWorkflow();bindRepricing();updateDateSummary();$('#content').oninput=()=>{updateDateSummary();markEdited();if($('#output'))$('#output').innerHTML='';if($('#readiness'))$('#readiness').innerHTML='';};}
function fileList(){return current.files.length?current.files.map((f,i)=>`<div class="file-row"><div><strong>${esc(f.name)}</strong><small>${Math.ceil(f.size/1024)} KB · ${f.hash?esc(f.hash.slice(0,10)):'eski kayıt'} · <span data-file-status="${i}">Dosya kontrol ediliyor…</span></small></div><select data-file-kind="${i}" aria-label="${esc(f.name)} belge türü">${Object.entries({model:'3D model',drawing:'2D teknik resim',request:'Müşteri talebi',other:'Diğer'}).map(([k,v])=>`<option value="${k}" ${(f.kind||fileKind(f.name))===k?'selected':''}>${v}</option>`).join('')}</select><button class="secondary file-download" data-index="${i}">Orijinali indir</button></div>`).join(''):'Henüz belge eklenmedi.';}

function options(v){return [['none','Yok'],['included','Var · Teklife dahil'],['excluded','Var · Kapsam dışı']].map(([a,b])=>`<option value="${a}" ${v===a?'selected':''}>${b}</option>`).join('');}
function altHtml(a,i){return `<div class="alternative" data-alt="${a.id}"><div class="alt-head"><span class="eyebrow">ALTERNATİF ${i+1}</span><button class="remove" aria-label="Alternatifi kaldır">×</button></div>${a.label?`<h3 class="alternative-label">${esc(a.label)}</h3>`:''}<label class="toggle">Teklif çıktısına dahil<input type="checkbox" data-field="offerIncluded" ${a.offerIncluded!==false?'checked':''}></label><button type="button" class="primary technical-open" data-id="${a.id}">3D incele ve kalıp taslağı oluştur</button><button type="button" class="secondary reprice-alternative" data-id="${a.id}">Güncel fiyatlarla yeni alternatif</button><label>Göz sayısı<input data-field="cavities" type="number" min="1" max="128" step="1" value="${a.cavities}"></label><label>Maça<select data-field="core">${options(a.core)}</select></label><label>Kızak mekanizması<select data-field="slide">${options(a.slide)}</select></label><p style="font-size:11px">Kalıp dış ölçüleri · mm</p><div class="measurements">${[['length','Boy'],['width','En'],['height','Yükseklik']].map(([k,v])=>`<label>${v}<input data-field="${k}" type="number" min="1" step="any" placeholder="—" value="${esc(a[k])}"></label>`).join('')}</div><label>Maça ölçüleri / notu<input data-field="coreSize" placeholder="Örn. 80 × 60 × 120 mm" value="${esc(a.coreSize)}"></label><label>Manuel teklif tutarı · EUR<input data-field="cost" type="number" min="0" step="0.01" placeholder="Henüz hesaplanmadı" value="${esc(a.cost)}"></label>${materialHtml(a)}${CostUI.render(a)}</div>`;}
function bindAlternatives(){bindMaterials();document.querySelectorAll('[data-alt]').forEach(el=>CostUI.bind(el,current.alternatives.find(a=>a.id===el.dataset.alt),markEdited,persist));bindRepricing();bindTechnicalButtons();document.querySelectorAll('.remove').forEach(b=>b.onclick=()=>{if(current.alternatives.length===1){toast('En az bir alternatif bulunmalı.');return;}capture();markEdited();current.alternatives=current.alternatives.filter(a=>a.id!==b.closest('[data-alt]').dataset.alt);$('#alternatives').innerHTML=current.alternatives.map(altHtml).join('');bindAlternatives();$('#output').innerHTML='';});}
function capture(){const before=Workflow.content(current);current.quoteDate=$('#quote-date').value;current.responseDue=$('#response-due').value;current.terms={};for(const k of QuoteTools.termKeys)current.terms[k]=document.querySelector(`[name="term-${k}"]`).value;current.updatedAt=new Date().toISOString();current.request=$('#request').value;current.language=$('#language').value;current.analysis=$('#analysis').value;document.querySelectorAll('[data-alt]').forEach(el=>{const a=current.alternatives.find(a=>a.id===el.dataset.alt);el.querySelectorAll('[data-field]').forEach(input=>{if(input.dataset.field==='offerIncluded'){if(a.offerIncluded!==undefined||!input.checked)a.offerIncluded=input.checked;}else a[input.dataset.field]=input.dataset.field==='cavities'?Number(input.value):input.value;});a.material={...a.material,...readMaterial(el)};Object.assign(a,CostUI.read(el,a));if(a.pricing.mode==='calculated'){const q=Costing.quote(a);a.cost=q.casting===null?'':String(Math.round(q.casting*100)/100);}});if(before!==Workflow.content(current)&&['ready','pending','approved','sent'].includes(current.status))Workflow.invalidate(current);updateWorkflowBadge();}
function preview(allowIncomplete=false){const invalid=[...document.querySelectorAll('[data-alt]')].filter(el=>el.querySelector('[data-field="offerIncluded"]').checked).flatMap(el=>[...el.querySelectorAll('input')]).find(e=>!e.checkValidity());if(invalid){invalid.reportValidity();return;}capture();const missing=Workflow.issues(current);$('#readiness').innerHTML=missing.length?`<section class="readiness panel body-pad"><h2>Çıktı öncesi kontrol · ${missing.length} eksik</h2><ul>${missing.map((m,i)=>`<li><button type="button" data-issue="${i}">${esc(m.text)} →</button></li>`).join('')}</ul><p>Eksikleri tamamlayın veya işaretli bir taslak ön izleme oluşturun.</p><button class="secondary" id="draft-preview">Eksiklerle taslak ön izleme</button></section>`:'<div class="notice">Tanımlı alan kontrolleri tamam. Otomatik mühendislik doğrulaması değildir.</div>';document.querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>document.querySelector(missing[Number(b.dataset.issue)].target)?.scrollIntoView({behavior:'smooth',block:'center'}));if(missing.length){$('#draft-preview').onclick=()=>preview(true);if(!allowIncomplete){$('#output').innerHTML='';$('#readiness').scrollIntoView({behavior:'smooth'});return;}}const supported=/\.(pdf|step|stp|x_t|x_b|igs|iges|catpart|catproduct|dwg|dxf|png|jpe?g)$/i;if(!current.files.some(f=>supported.test(f.name))){toast('En az bir 2D teknik resim veya 3D model seçin.');return;}if(!persist())return;const en=current.language==='en',t=(a,b)=>en?b:a;const state=v=>v==='included'?t('Dahil','Included'):v==='excluded'?t('Kapsam dışı','Excluded'):t('Yok','None');$('#output').innerHTML=`<div class="actions"><button id="save-output" class="secondary">${t('Çıktıyı kaydet','Save document')}</button><button id="print" class="secondary">${t('Yazdır / PDF olarak kaydet','Print / Save as PDF')}</button></div><article class="output" lang="${en?'en':'tr'}">${Settings.brand(current,en)}${!Workflow.approved(current)?`<div class="notice">${en?'UNAPPROVED DRAFT':'ONAYLANMAMIŞ TASLAK'}</div>`:`<p>${en?'Approved':'Onaylandı'}: ${esc(new Date(current.approval.at).toLocaleString('tr-TR'))}</p>`}${missing.length?`<div class="notice">${en?'INCOMPLETE DRAFT — review required':'EKSİK BİLGİ İÇEREN TASLAK — kontrol gerektirir'}</div>`:''}<div class="eyebrow">LS MOLDWORKS · ${en?({draft:'IN PREPARATION',ready:'READY',pending:'PENDING APPROVAL',sent:'SENT',revision:'REVISION REQUESTED',approved:'APPROVED',cancelled:'CANCELLED'}[statusOf(current)]):statuses[statusOf(current)]}</div><h1>${t('Kalıp Teklifi','Mold Quotation')} / ${esc(current.code)}</h1><p><strong>${esc(current.customer)}</strong><br>${[current.customerInfo?.contact,current.customerInfo?.email,current.customerInfo?.address].filter(Boolean).map(esc).join('<br>')}<br>${esc(current.part)} · ${QuoteDates.format(QuoteDates.quoteDate(current))}</p>${quotePartImage(current)}<div class="notice">${t('Tutarlar EUR cinsindendir. Göz alternatifleri ayrı seçeneklerdir; birbirine eklenmez.','Amounts are in EUR. Cavity alternatives are separate options and are not cumulative.')}</div><table><thead><tr><th>${t('ALTERNATİF','OPTION')}</th><th>${t('KALIP ÖLÇÜLERİ','MOLD DIMENSIONS')}</th><th>${t('MAÇA / KIZAK','CORE / SLIDE')}</th><th>${t('MAÇA ÖLÇÜLERİ','CORE DIMENSIONS')}</th><th>${t('DÖKÜM','CASTING')} · EUR</th><th>TRIM · EUR</th><th>${t('TOPLAM','TOTAL')} · EUR</th></tr></thead><tbody>${current.alternatives.filter(a=>a.offerIncluded!==false).map((a,i)=>`<tr><td>${i+1} · ${esc(a.cavities)} ${t('göz','cavities')}</td><td>${[a.length,a.width,a.height].every(Boolean)?[a.length,a.width,a.height].map(esc).join(' × ')+' mm':t('Belirtilmedi','Not specified')}</td><td>${state(a.core)} / ${state(a.slide)}</td><td>${a.core==='none'?'—':esc(a.coreSize)||'—'}</td><td>${Costing.quote(a).casting===null?t('Belirlenmedi','Not priced'):Costing.quote(a).casting.toFixed(2)}</td><td>${a.pricing?.trimEnabled?(Costing.quote(a).trim===null?'—':Costing.quote(a).trim.toFixed(2)):t('Hariç','Excluded')}</td><td>${Costing.quote(a).total===null?'—':Costing.quote(a).total.toFixed(2)}</td></tr>`).join('')}</tbody></table>${$('#include-analysis').checked?`<h2 style="margin-top:30px">${t('Parça İnceleme ve Analiz Özeti','Part Review and Analysis Summary')}</h2><p style="white-space:pre-wrap">${esc(current.analysis)||t('Teknik inceleme henüz yapılmadı.','Technical review has not yet been performed.')}</p>`:''}<h2>${t('Teklif Koşulları','Sales Terms & Conditions')}</h2><dl class="quote-conditions">${[['payment',t('Ödeme','Payment')],['delivery',t('Teslim şekli','Delivery')],['lead',t('Teslim süresi','Lead time')]].map(([k,title])=>`<dt>${title}</dt><dd>${esc(current.terms?.[k+(en?'En':'Tr')])||'—'}</dd>`).join('')}<dt>${t('Geçerlilik süresi','Validity')}</dt><dd>${esc(current.terms?.validityDays)||'—'} ${t('gün (teklif tarihinden itibaren)','days from quotation date')} · ${t('Son gün','Valid until')}: ${QuoteDates.format(QuoteDates.validUntil(current))}</dd></dl><p style="white-space:pre-wrap">${esc(current.request)}</p></article>`;$('#save-output').onclick=()=>exportQuoteOutput(true).catch(error=>toast(error.message));$('#print').onclick=()=>{capture();if(!Workflow.approved(current))toast('Bu çıktı onaylanmamış taslaktır.');window.print();};$('#output').scrollIntoView({behavior:'smooth'});}
function filterButtons(){return (view==='approvals'?['ready','pending','approved'].map(k=>[k,statuses[k]]):[['all','Tümü'],...Object.entries(statuses)]).map(([v,t])=>`<button data-filter="${v}" aria-pressed="${statusFilter===v}" class="filter-chip ${statusFilter===v?'selected':''}">${t}</button>`).join('');}
function bindFilters(){document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{statusFilter=b.dataset.filter;$('#rows').innerHTML=rows($('#search').value);document.querySelectorAll('[data-filter]').forEach(el=>{el.setAttribute('aria-pressed',String(el.dataset.filter===statusFilter));el.classList.toggle('selected',el.dataset.filter===statusFilter);});bindOpen();});}
function quickAction(id,action){const source=projects.find(p=>p.id===id);if(!source)return;
 if(action==='pdf'){openProject(id);document.querySelector('#language').focus();document.querySelector('#language').scrollIntoView({behavior:'smooth',block:'center'});toast('Çıktı dilini seçip ön izleme oluşturun; ardından PDF olarak yazdırın.');return;}
 const copy=structuredClone(source);copy.id=crypto.randomUUID();copy.created=copy.updatedAt=new Date().toISOString();copy.quoteDate=QuoteDates.today();if(action==='copy')copy.responseDue='';Workflow.invalidate(copy);
 if(action==='revision'){copy.revision=Math.max(...projects.filter(p=>p.base===source.base).map(p=>p.revision||0))+1;copy.code=source.base+'_rev'+copy.revision;}
 else{const year=String(new Date().getFullYear()).slice(-2),prefix=source.prefix,stem=prefix+year;const num=Math.max(0,...projects.filter(p=>p.prefix===prefix&&p.year===year).map(p=>Number(p.base.slice(stem.length))||0))+1;if(num>999){toast('Yıllık teklif kodu sınırına ulaşıldı.');return;}const customer=Customers.get(copy.customerId);if(customer){copy.customerInfo=customer;copy.customer=customer.name;copy.language=customer.language;}copy.year=year;copy.revision=0;copy.code=copy.base=stem+String(num).padStart(3,'0');}
 projects.push(copy);if(!persist()){projects.pop();return;}openProject(copy.id);toast(action==='revision'?'Yeni revizyon oluşturuldu; önceki kayıt korundu.':'Yeni kodla teklif kopyalandı.');
}
async function uploadThumbnail(e){const file=e.target.files[0],project=current;if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){toast('En fazla 5 MB boyutunda PNG, JPG veya WebP seçin.');e.target.value='';return;}const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,320/img.width,240/img.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);if(current!==project)return;markEdited();project.thumbnail=canvas.toDataURL('image/png');$('#thumbnail-current').innerHTML=thumbnail(project);$('#output').innerHTML='';toast('Ön izleme hazır. Projeyi kaydetmeyi unutmayın.');}catch{toast('Görsel okunamadı. Başka bir görsel deneyin.');}finally{URL.revokeObjectURL(url);}}
window.addEventListener('ls-restore-folder',e=>{current=null;view='backup';renderBackup();const input=$('#import-backup'),dt=new DataTransfer();dt.items.add(new File([JSON.stringify(e.detail)],'workspace.json',{type:'application/json'}));input.files=dt.files;input.dataset.folderRestore='true';input.dispatchEvent(new Event('change'));});window.LSArchive={snapshot:archiveSnapshot};window.addEventListener('ls-data-saved',()=>{try{WorkspaceStore.sync(archiveSnapshot()).catch(()=>{});}catch(error){console.warn('Arşiv senkronu başlatılamadı.');}});WorkspaceStore.init();
if(Customers.ensure(projects))persist();
renderHome();

const materialDefaults={partX:'',partY:'',referenceSize:'',edge:70,threshold:100,growth:0.5,columns:1,rows:1,gap:40,quantity:2,density:7850,thickness:'',price:'',manualX:'',manualY:''};
function materialHtml(a){const p={...materialDefaults,...a.material};const field=(k,label,extra='')=>`<label>${label}<input data-material="${k}" type="number" step="any" ${extra||'min="0"'} value="${esc(p[k])}"></label>`;return `<details class="material-panel"><summary>Malzeme ön hesabı · mm / kg</summary><div class="notice">Kural v2: 100 mm’ye kadar her kenarda 70 mm. Üzerindeki artış katsayısı geçici varsayımdır: varsayılan her +10 mm için +5 mm (ara ölçülerde orantılı artış). Göz arası 40 mm ve iki blok da deneme varsayımlarıdır. Maçalı düzen, hamiller, piston ve hırdavat otomatik boyutlandırılmaz. Bu sonuç tam kalıp bedeli değildir.</div><div class="two">${field('partX','Parça X · mm')}${field('partY','Parça Y · mm')}${field('referenceSize','Varsa diğer büyük parça ölçüsü · mm')}${field('threshold','Temel boyut sınırı · mm')}${field('edge','Her kenardaki temel pay · mm')}${field('growth','Sınır üstü artış · mm/mm')}${field('columns','Yerleşim sütunu','min="1"')}${field('rows','Yerleşim satırı','min="1"')}${field('gap','Gözler arası net mesafe · mm')}${field('quantity','Aynı ölçüde ham blok adedi','min="1"')}${field('thickness','Her bloğun ham kalınlığı · mm')}${field('density','Yoğunluk · kg/m³')}${field('manualX','Manuel blok X · mm (isteğe bağlı)')}${field('manualY','Manuel blok Y · mm (isteğe bağlı)')}${field('price','Çelik kg fiyatı · EUR (isteğe bağlı)')}</div><label>Çelik kataloğundan seç<select class="steel-choice"><option value="">Çelik seçin…</option>${Settings.get().steels.map((s,i)=>`<option value="${i}">${esc(s.name)} · ${s.price===''?'fiyat bekliyor':esc(s.price)+' EUR/kg'}</option>`).join('')}</select></label><div class="actions"><button type="button" class="secondary apply-steel">Seçilen çeliği uygula</button><button type="button" class="secondary apply-rules">Güncel kenar kuralını uygula</button></div><div class="material-result" aria-live="polite"></div><small>Öneri yalnızca çekirdek bloğu ön hesabıdır. Bitmiş kalıp dış ölçüleri değildir. Manuel teklif tutarını değiştirmez.</small></details>`;}
function readMaterial(el){const p={};el.querySelectorAll('[data-material]').forEach(i=>p[i.dataset.material]=i.value);return p;}
function bindMaterials(){document.querySelectorAll('[data-alt]').forEach(el=>{const a=current.alternatives.find(a=>a.id===el.dataset.alt);const update=()=>{const p=readMaterial(el),r=Materials.calculate(p),result=el.querySelector('.material-result'),n=v=>v.toLocaleString('tr-TR',{maximumFractionDigits:2});if(r.error){result.textContent=r.error;return;}const a=current.alternatives.find(a=>a.id===el.dataset.alt);result.innerHTML=`<strong>Kenar payı: ${n(r.margin)} mm</strong><p>Önerilen ham blok: ${n(r.suggestedX)} × ${n(r.suggestedY)} mm<br>Kullanılan blok: ${n(r.length)} × ${n(r.width)} × ${r.thickness===null?'kalınlık bekliyor':n(r.thickness)+' mm'}<br>Toplam ağırlık: ${r.mass===null?'Kalınlık girin':n(r.mass)+' kg'}<br>Malzeme bedeli: ${r.cost===null?'Ölçü / kg fiyatı bekliyor':n(r.cost)+' EUR'}</p>${Number(p.rows)*Number(p.columns)!==Number(el.querySelector('[data-field="cavities"]').value)?'<div class="notice">Yerleşim göz sayısıyla eşleşmiyor.</div>':''}${el.querySelector('[data-field="core"]').value!=='none'||el.querySelector('[data-field="slide"]').value!=='none'?'<div class="notice">Maça/kızak var: Bu aç-kapa kuralı mekanizma için gereken alanı hesaplamaz. Ölçüler mühendislik incelemesi gerektirir.</div>':''}${r.tooSmall?'<div class="notice">Manuel ölçü temel öneriden küçük; kontrol edin.</div>':''}`;};el.querySelector('.apply-steel').onclick=()=>{const choice=el.querySelector('.steel-choice').value;if(choice===''){toast('Önce bir çelik seçin.');return;}const steel=Settings.get().steels[Number(choice)];a.material={...a.material,steelName:steel.name,priceUpdatedAt:steel.updatedAt||'',priceAtRate:String(steel.price)};for(const [k,v] of Object.entries({price:steel.price,density:steel.density}))el.querySelector(`[data-material="${k}"]`).value=v;update();$('#output').innerHTML='';};el.querySelector('.apply-rules').onclick=()=>{const s=Settings.get();for(const k of ['edge','threshold','growth'])el.querySelector(`[data-material="${k}"]`).value=s[k];update();$('#output').innerHTML='';};el.querySelectorAll('[data-material],[data-field="cavities"],[data-field="core"],[data-field="slide"]').forEach(i=>i.addEventListener('input',update));update();});}

function renderBackup(){
 $('#breadcrumb').textContent='Yedekleme';document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view==='backup'));
 $('#content').innerHTML=heading('Yedekleme ve Geri Yükleme','Kaydedilmiş teklifleri, firma logosunu ve ayarları tek dosyada saklayın.',false)+`<section class="panel body-pad"><h2>Yedek dosyası indir</h2><p>Yedek, kaydedilmiş teklifleri ve firma ayarlarını içerir. JSON yedeği orijinal dosya içeriklerini içermez. Tam dosyalar için proje ZIP paketini veya seçilen arşiv klasörünü kullanın. Kaydetmediğiniz değişiklikler yedeğe alınmaz.</p><button class="primary" id="export-backup">Yedeği indir · JSON</button></section><section class="panel body-pad"><h2>Yedekten geri yükle</h2><label>LS MoldWorks JSON / ZIP yedek dosyası<input id="import-backup" type="file" accept=".json,.zip,application/json,application/zip"><small>JSON en fazla 20 MB, LS MoldWorks ZIP paketi 250 MB. Dosya önce kontrol edilir; kendiliğinden uygulanmaz.</small></label><div id="backup-review" role="status"></div></section>`;
 $('#export-backup').onclick=()=>{try{const data=archiveSnapshot();QuoteTools.validateBackup(data);const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='LS-MoldWorks-yedek-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Yedek dosyası indirildi.');}catch{toast('Yedek oluşturulamadı. Kayıtları kontrol edin.');}};
 $('#import-backup').onchange=async e=>{const file=e.target.files[0];if(!file)return;const isFolderData=e.target.dataset.folderRestore==='true';delete e.target.dataset.folderRestore;const review=$('#backup-review');review.textContent='Dosya kontrol ediliyor…';try{const data=await parseBackupFile(file);if(!review.isConnected)return;const conflicts=data.projects.filter(p=>projects.some(old=>old.id===p.id||old.code===p.code)),incoming=data.projects.filter(p=>!conflicts.includes(p));review.innerHTML=`<div class="notice">${data.projects.length} teklif kaydı bulundu.${data.fileRestoreSummary?` Orijinal dosya: ${data.fileRestoreSummary.restored} bağlandı, ${data.fileRestoreSummary.missing} eksik.`:''} ${incoming.length} yeni kayıt eklenebilir. ${conflicts.length} çakışan kayıt atlanacak; mevcut teklifler değiştirilmez.<br>Orijinal CAD/PDF içerikleri JSON yedeğinde bulunmaz. Klasör arşivi açılıyorsa dosyalar ayrıca doğrulanıp bağlanır.</div><label class="toggle" style="max-width:480px">Firma ayarlarını, katalogları ve logoyu da yedektekiyle değiştir<input id="restore-settings" type="checkbox"></label><p>Firma ayarlarını değiştireceksen önce mevcut yedeğini indirmeni öneririz.</p><button id="apply-backup" class="primary">Seçilen verileri geri yükle</button>`;
 $('#apply-backup').onclick=()=>{const restoreSettings=$('#restore-settings').checked,oldProjects=localStorage.getItem(key),settingsKey='ls-moldworks-settings-v1',oldSettings=localStorage.getItem(settingsKey),customersKey='ls-moldworks-customers-v1',oldCustomers=localStorage.getItem(customersKey);try{const clients=Customers.all(),remap=new Map();for(const c of data.customers||[]){const same=clients.find(x=>x.id===c.id||x.prefix===c.prefix||x.name.toLocaleLowerCase('tr')===c.name.toLocaleLowerCase('tr'));if(same)remap.set(c.id,same.id);else clients.push(c);}const additions=structuredClone(incoming);for(const p of additions)if(remap.has(p.customerId))p.customerId=remap.get(p.customerId);const merged=[...projects,...additions];localStorage.setItem(customersKey,JSON.stringify(clients));localStorage.setItem(key,JSON.stringify(merged));if(restoreSettings)localStorage.setItem(settingsKey,JSON.stringify(data.settings));Customers.reload();projects=merged;Customers.ensure(projects);localStorage.setItem(key,JSON.stringify(projects));projects.forEach(p=>{if(!p.issuer)p.issuer={};});if(restoreSettings)Settings.reload();if(isFolderData)WorkspaceStore.acceptLoadedArchive();window.dispatchEvent(new Event('ls-data-saved'));review.textContent=`Geri yükleme tamamlandı: ${incoming.length} kayıt eklendi, ${conflicts.length} kayıt atlandı.${restoreSettings?' Firma ayarları güncellendi.':''}`;toast('Yedek geri yüklendi.');}catch{try{if(oldProjects===null)localStorage.removeItem(key);else localStorage.setItem(key,oldProjects);if(oldSettings===null)localStorage.removeItem(settingsKey);else localStorage.setItem(settingsKey,oldSettings);if(oldCustomers===null)localStorage.removeItem(customersKey);else localStorage.setItem(customersKey,oldCustomers);Customers.reload();projects=JSON.parse(oldProjects||'[]');}catch{}review.textContent='Geri yükleme başarısız. Depolama alanını kontrol edin; sayfayı yenilemeden önce mevcut yedeğinizi saklayın.';}};
 }catch(error){if(review.isConnected)review.textContent='Dosya yüklenemedi: '+(error instanceof SyntaxError?'Geçerli bir JSON dosyası değil.':error.message);}};
}

function populateCustomers(){const select=$('#customer-select'),form=$('#project-form');select.innerHTML='<option value="">Yeni müşteri / manuel giriş</option>'+Customers.all().map(c=>`<option value="${c.id}">${esc(c.name)} (${esc(c.prefix)})</option>`).join('');select.value='';form.elements.customer.readOnly=false;form.elements.prefix.readOnly=false;select.onchange=()=>{const c=Customers.get(select.value);form.elements.customer.readOnly=!!c;form.elements.prefix.readOnly=!!c;if(c){form.elements.customer.value=c.name;form.elements.prefix.value=c.prefix;}else{form.elements.customer.value='';form.elements.prefix.value='';}};}
async function addProjectFiles(e){const project=current,selected=[...e.target.files];if(selected.length)delete project.confirmedReference;for(const f of selected){if(f.size>50*1024*1024){toast(f.name+': 50 MB sınırını aşıyor.');continue;}try{const bytes=await f.arrayBuffer(),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('');await Attachments.put(hash,f);let entry=project.files.find(x=>x.hash===hash);if(!entry){entry=project.files.find(x=>!x.hash&&x.name===f.name&&x.size===f.size);if(entry)entry.hash=hash;else{entry={name:f.name,size:f.size,hash};project.files.push(entry);}}
entry.binary=true;entry.kind=entry.kind||fileKind(f.name);entry.addedAt=entry.addedAt||new Date().toISOString();if(current===project){$('#file-list').innerHTML=fileList();bindFileActions();renderModelMatches();}
if(/\.(step|stp|igs|iges|x_t|x_b|catpart|catproduct)$/i.test(f.name)&&!ModelSearch.valid(entry.geometry)){
 const cached=projects.flatMap(p=>p.files).find(x=>x.hash===hash&&ModelSearch.valid(x.geometry));
 if(cached)entry.geometry=structuredClone(cached.geometry);
 else{if(current===project)$('#model-matches').insertAdjacentHTML('afterbegin','<div class="notice geometry-progress">STEP geometrisi analiz ediliyor…</div>');try{const response=await fetch('/api/geometry?filename='+encodeURIComponent(f.name),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:bytes});const result=await response.json();if(!response.ok||!ModelSearch.valid(result))throw new Error(result.error||'Geometri yanıtı geçersiz.');entry.geometry=result;delete entry.geometryError;}catch(error){entry.geometryError=error.message;}}
}
}catch{toast(f.name+': dosya işlenemedi.');}}
if(current!==project)return;markEdited();$('#file-list').innerHTML=fileList();bindFileActions();$('#output').innerHTML='';renderModelMatches();bindDocumentIntake();toast('Dosya işlemi tamamlandı. Sonuçları korumak için projeyi kaydedin.');}
function renderModelMatches(){const box=$('#model-matches');if(!box)return;
 const models=current.files.filter(f=>/\.(stp|step|x_t|x_b|igs|iges|catpart|catproduct)$/i.test(f.name)&&f.hash);
 const matches=[];
 for(const p of projects){if(p.id===current.id)continue;let best=null;for(const a of models)for(const b of p.files){if(a.hash===b.hash){best={exact:true,maximum:0};break;}const score=ModelSearch.compare(a.geometry,b.geometry);if(score&&(!best||!best.exact&&score.maximum<best.maximum))best=score;}if(best)matches.push({p,score:best});}
 matches.sort((a,b)=>Number(b.score.exact||false)-Number(a.score.exact||false)||a.score.maximum-b.score.maximum);
 const indexed=projects.filter(p=>p.id!==current.id&&p.files.some(f=>ModelSearch.valid(f.geometry))).length;
 box.innerHTML=`<h3>Parça adından bağımsız eski teklif arama</h3>${referenceHtml()}<p>Arşivde geometrisi indekslenmiş ${indexed} teklif tarandı. STEP için hacim, yüzey alanı ve asal atalet değerleri karşılaştırılır; ad, konum ve yön kullanılmaz. Yakın sonuçlar adaydır: sağ/sol ve farklı geometriler benzer özellikler taşıyabilir. Eski kayıtları indekslemek için STEP dosyasını yeniden seçip kaydedin. Diğer CAD formatlarında şimdilik yalnızca aynı dosya içeriği aranır.</p>${current.files.filter(f=>f.geometryError).map(f=>`<div class="notice">${esc(f.name)}: ${esc(f.geometryError)}</div>`).join('')}${matches.length?matches.map(({p,score})=>`<div class="match-row"><div><strong>${esc(p.code)} · ${esc(p.customer)}</strong><p>${esc(p.part)} · ${date(p.created)}<br>${p.alternatives.map(a=>esc(a.cavities)+' göz: '+(a.cost===''?'fiyat yok':esc(a.cost)+' EUR')).join(' / ')}</p><span class="badge">${score.exact?'Aynı dosya içeriği':score.level==='close'?'Geometrik özellikleri çok yakın':'Geometrik benzerlik adayı'}${p.customerId===current.customerId?' · Aynı müşteri':' · Farklı müşteri'}</span>${score.exact?'':`<p>Hacim farkı %${(score.volume*100).toFixed(2)} · Yüzey farkı %${(score.area*100).toFixed(2)} · Atalet farkı %${(score.inertia*100).toFixed(2)}</p>`}</div><button class="secondary compare-project" data-id="${p.id}">Karşılaştır</button></div>`).join(''):`<small>${models.length?'Kayıtlı modellerde karşılaştırma sınırına giren aday bulunamadı.':'3D dosya seçildiğinde önceki teklif adayları burada gösterilir.'}</small>`}<div id="comparison-result"></div>`;box.querySelectorAll('.compare-project').forEach(b=>b.onclick=()=>compareProject(b.dataset.id));if($('#clear-reference'))$('#clear-reference').onclick=()=>{markEdited();const old=current.confirmedReference;delete current.confirmedReference;if(!persist())current.confirmedReference=old;renderModelMatches();};}

function compareProject(id){capture();const previous=projects.find(p=>p.id===id);if(!previous)return;const n=v=>Number(v).toLocaleString('tr-TR',{maximumFractionDigits:2});$('#comparison-result').innerHTML=`<div class="notice">Referans: ${esc(previous.code)} · ${esc(previous.customer)}. Eski fiyatlar bugünkü maliyet veya önerilen satış fiyatı değildir. Farklar kayıtlı alternatif sırasına göre gösterilir; farklı kapsamları kontrol edin.</div><div class="table-wrap"><table><thead><tr><th>ALTERNATİF</th><th>ÖNCEKİ</th><th>MEVCUT</th><th>TUTAR FARKI · EUR</th></tr></thead><tbody>${Array.from({length:Math.max(previous.alternatives.length,current.alternatives.length)},(_,i)=>{const a=previous.alternatives[i],b=current.alternatives[i];const summary=x=>!x?'—':`${esc(x.cavities)} göz · Maça: ${esc(x.core)} · Kızak: ${esc(x.slide)}<br>${[x.length,x.width,x.height].map(v=>esc(v)||'—').join(' × ')} mm<br>${x.cost!==''&&x.cost!=null?n(x.cost)+' EUR':'Tutar yok'}`;return `<tr><td>${i+1}</td><td>${summary(a)}</td><td>${summary(b)}</td><td>${a&&b&&a.cost!==''&&b.cost!==''?n(Number(b.cost)-Number(a.cost)):'Hesaplanamadı'}</td></tr>`;}).join('')}</tbody></table></div><div class="actions"><button id="confirm-reference" class="primary">Aynı parça mı? İncele ve onayla</button><button id="open-reference" class="secondary">Eski teklifi aç</button></div>`;$('#confirm-reference').onclick=()=>confirmReference(previous);$('#open-reference').onclick=()=>{if(!persist())return;openProject(previous.id);};}

function referenceHtml(){const r=current.confirmedReference;if(!r)return '<div class="notice">Henüz aynı parça onayı verilmedi. Hiçbir aday referans olarak bağlanmadı.</div>';return `<div class="reference-approved"><strong>Kullanıcı onaylı parça referansı: ${esc(r.code)}</strong><p>Onay tarihi: ${esc(new Date(r.confirmedAt).toLocaleString('tr-TR'))}. Bu bir kullanıcı kararıdır; otomatik geometrik eşitlik doğrulaması değildir. Eski fiyat aktarılmadı.</p><button id="clear-reference" class="secondary">Bağlantıyı kaldır</button></div>`;}
function confirmReference(previous){const project=current;document.querySelector('#reference-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='reference-dialog';const card=(p,title)=>`<div class="reference-card"><span class="eyebrow">${title}</span>${thumbnail(p)}<h3>${esc(p.part)}</h3><p>${esc(p.customer)} · ${esc(p.code)}<br>${p.files.filter(f=>/\.(stp|step|x_t|x_b|igs|iges|catpart|catproduct)$/i.test(f.name)).map(f=>esc(f.name)).join('<br>')}</p></div>`;dialog.innerHTML=`<h2>Aynı parça olduğunu doğrulayın</h2><p>Hacim, alan ve atalet benzerliği tek başına aynı parça olduğunu kanıtlamaz. Sağ/sol, delikler, toleranslar ve revizyon farklılıklarını kontrol edin.</p><div class="two">${card(project,'YENİ TEKLİF')}${card(previous,'ARŞİVDEKİ ADAY')}</div><div class="notice">Bu onay yalnızca referans bağlantısı kurar. Mevcut ölçü, kapsam ve fiyat değiştirilmez. Görseller yoksa veya emin değilseniz onaylamayın.</div><label class="toggle">Parçaları kontrol ettim; aynı parça olduğunu onaylıyorum.<input id="same-part-check" type="checkbox"></label><div class="actions"><button id="accept-reference" class="primary" disabled>Referans olarak bağla</button><button id="reject-reference" class="secondary">Farklı parça / Emin değilim</button></div>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('#same-part-check').onchange=e=>dialog.querySelector('#accept-reference').disabled=!e.target.checked;dialog.querySelector('#reject-reference').onclick=()=>{dialog.close();dialog.remove();toast('Aday bağlanmadı.');};dialog.querySelector('#accept-reference').onclick=()=>{if(current!==project||!dialog.querySelector('#same-part-check').checked)return;const old=project.confirmedReference;markEdited();project.confirmedReference={projectId:previous.id,code:previous.code,confirmedAt:new Date().toISOString(),method:'user-confirmed',modelHashes:project.files.filter(f=>f.hash).map(f=>f.hash)};if(!persist()){if(old)project.confirmedReference=old;else delete project.confirmedReference;return;}dialog.close();dialog.remove();renderModelMatches();toast('Aynı parça onayı kaydedildi. Eski fiyat aktarılmadı.');};dialog.addEventListener('cancel',()=>dialog.remove());}

function archiveSnapshot(){return {format:'ls-moldworks-backup',version:1,exportedAt:new Date().toISOString(),projects:JSON.parse(localStorage.getItem(key)||'[]'),settings:Settings.get(),customers:Customers.all()};}
function workflowHtml(p){return `<section class="workflow-box"><div><span class="eyebrow">TEKLİF KONTROLÜ</span><h3>Hazırla → Onaya gönder → İncele ve onayla</h3><p>Onaylanmamış çıktılar taslak olarak işaretlenir. İçerik değişirse yeniden onay gerekir.</p></div><div class="actions"><button id="mark-ready" class="secondary" ${p.status==='approved'?'disabled':''}>Hazır olarak kaydet</button><button id="submit-approval" class="primary" ${p.status!=='ready'?'disabled':''}>Onaya gönder</button><button id="review-approval" class="primary" ${p.status!=='pending'?'disabled':''}>İncele ve onayla</button></div><div id="workflow-message" role="status"></div></section>`;}
function updateWorkflowBadge(){if(!current)return;const el=$('#workflow-status');if(el)el.textContent=statuses[statusOf(current)];if($('#mark-ready'))$('#mark-ready').disabled=current.status==='approved';if($('#submit-approval'))$('#submit-approval').disabled=current.status!=='ready';if($('#review-approval'))$('#review-approval').disabled=current.status!=='pending';}
function markEdited(){if(!current)return;if(['ready','pending','approved','sent'].includes(current.status)){Workflow.invalidate(current);updateWorkflowBadge();if($('#workflow-message'))$('#workflow-message').textContent='İçerik değişti. Teklif yeniden hazırlanmalı ve onaylanmalı.';}if($('#output'))$('#output').innerHTML='';}
function showWorkflowIssues(){const missing=Workflow.issues(current);$('#workflow-message').innerHTML=missing.length?`<div class="notice"><strong>${missing.length} eksik / kontrol:</strong><ul>${missing.map((m,i)=>`<li><button data-workflow-issue="${i}">${esc(m.text)} →</button></li>`).join('')}</ul></div>`:'';document.querySelectorAll('[data-workflow-issue]').forEach(b=>b.onclick=()=>document.querySelector(missing[Number(b.dataset.workflowIssue)].target)?.scrollIntoView({behavior:'smooth',block:'center'}));return missing;}
async function saveWorkspaceMessage(message){if(!persist())return false;try{await WorkspaceStore.sync(archiveSnapshot());if($('#workflow-message'))$('#workflow-message').textContent=message+(WorkspaceStore.getPreference().mode==='folder'?' Seçilen klasöre de yazıldı.':' Tarayıcıya kaydedildi.');toast(message);return true;}catch(error){if($('#workflow-message'))$('#workflow-message').textContent=message+' Tarayıcı kopyası var; seçilen klasöre kayıt tamamlanamadı: '+error.message;return false;}}
function bindWorkflow(){
 $('#save').onclick=async()=>{capture();await saveWorkspaceMessage('Teklif kaydedildi.');};
 $('#mark-ready').onclick=async()=>{capture();if(showWorkflowIssues().length||!await checkOriginalFiles())return;try{Workflow.transition(current,'ready');updateWorkflowBadge();await saveWorkspaceMessage('Teklif hazır.');}catch(error){$('#workflow-message').textContent=error.message;}};
 $('#submit-approval').onclick=async()=>{capture();if(showWorkflowIssues().length||!await checkOriginalFiles())return;try{Workflow.transition(current,'pending');updateWorkflowBadge();await saveWorkspaceMessage('Teklif onay bekliyor.');}catch(error){$('#workflow-message').textContent=error.message;}};
 $('#review-approval').onclick=async()=>{capture();if(current.status!=='pending'||showWorkflowIssues().length||!await checkOriginalFiles())return;openApprovalDialog();};
}
function openApprovalDialog(){const project=current,reviewedContent=Workflow.content(project);document.querySelector('#approval-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='approval-dialog';dialog.className='approval-dialog';dialog.innerHTML=`<span class="eyebrow">TEKLİF SON KONTROLÜ</span><h2>${esc(project.code)} · ${esc(project.customer)}</h2><p>${esc(project.part)} · Çıktı dili: ${project.language==='en'?'İngilizce':'Türkçe'}</p><div class="approval-summary">${project.alternatives.filter(a=>a.offerIncluded!==false).map((a,i)=>`<section><h3>Alternatif ${i+1} · ${esc(a.cavities)} göz</h3><p>Kalıp: ${[a.length,a.width,a.height].map(esc).join(' × ')} mm<br>Maça: ${esc(a.core)} · Kızak: ${esc(a.slide)}</p>${CostUI.summaryHtml(a)}</section>`).join('')}</div><h3>Teklif koşulları</h3><p>${['payment','delivery','lead'].map(k=>esc(project.terms[k+(project.language==='en'?'En':'Tr')])).join('<br>')}<br>Geçerlilik: ${esc(project.terms.validityDays)} gün</p><div class="notice">Bu onay teklifin iç kontrolüdür; müşteri sipariş onayı değildir. Parça, sağ/sol düzeni, model eşleşmesi, ölçüler, maliyet ve ticari koşulları kontrol edin. Otomatik mühendislik doğrulaması yapılmaz.</div><label class="toggle">Teklifi inceledim, bu içerik ve tutarları onaylıyorum.<input id="approval-reviewed" type="checkbox"></label><div class="actions"><button class="primary" id="approve-final" disabled>Teklifi onayla ve kaydet</button><button class="secondary" id="cancel-approval">İncelemeye geri dön</button></div><p id="approval-result" role="status"></p>`;document.body.append(dialog);dialog.showModal();$('#approval-reviewed').onchange=e=>$('#approve-final').disabled=!e.target.checked;$('#cancel-approval').onclick=()=>{dialog.close();dialog.remove();};$('#approve-final').onclick=async()=>{if(current!==project||Workflow.content(project)!==reviewedContent){$('#approval-result').textContent='İçerik değişti. Tekrar inceleyin.';return;}try{Workflow.transition(project,'approved',$('#approval-reviewed').checked);updateWorkflowBadge();$('#approve-final').disabled=true;const okay=await saveWorkspaceMessage('Teklif onaylandı.');if(!okay){project.status='pending';delete project.approval;persist();updateWorkflowBadge();$('#approval-result').textContent='Onay tamamlanmadı: kayıt konumuna yazılamadı. Teklif onay bekliyor durumuna döndü. Kayıt konumunu kontrol edin.';$('#approve-final').disabled=false;return;}preview();try{await exportQuoteOutput(false);}catch(error){project.status='pending';delete project.approval;persist();updateWorkflowBadge();$('#output').innerHTML='';$('#approval-result').textContent='Onaylı çıktı klasöre yazılamadı. Onay tamamlanmadı: '+error.message;$('#approve-final').disabled=false;return;}dialog.close();dialog.remove();}catch(error){$('#approval-result').textContent=error.message;}};dialog.addEventListener('cancel',()=>dialog.remove());}

async function exportQuoteOutput(downloadWhenBrowser=true){const output=$('.output');if(!output||!current)throw new Error('Önce güncel teklif ön izlemesini oluşturun.');const project=current,content=Workflow.content(project);const css=await (await fetch('/style.css')).text();if(current!==project||Workflow.content(project)!==content)throw new Error('Teklif değişti. Ön izlemeyi yeniden oluşturun.');const html='<!doctype html><html lang="'+project.language+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(project.code)+'</title><style>'+css+' body{background:white;padding:25px}.output{max-width:1100px;margin:auto}.output .notice{display:block!important}</style></head><body>'+output.outerHTML+'</body></html>';await Attachments.outputPut(project,html);if(WorkspaceStore.getPreference().mode==='folder'){const filename=await WorkspaceStore.saveOutput(project,html);toast('Çıktı kaydedildi: '+filename);}else if(downloadWhenBrowser){const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=project.code+(Workflow.approved(project)?'.approved.html':'.draft.html');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Yazdırılabilir teklif dosyası indirildi.');}}

function fileKind(name){return /\.(stp|step|x_t|x_b|catpart|catproduct|igs|iges)$/i.test(name)?'model':/\.(eml|txt)$/i.test(name)?'request':/\.(pdf|png|jpe?g|dwg|dxf)$/i.test(name)?'drawing':'other';}
function bindFileActions(){const project=current;if(!project)return;document.querySelectorAll('[data-file-kind]').forEach(s=>s.onchange=()=>{project.files[Number(s.dataset.fileKind)].kind=s.value;markEdited();});document.querySelectorAll('.file-download').forEach(b=>b.onclick=async()=>{const f=project.files[Number(b.dataset.index)];try{const blob=await WorkspaceStore.readAttachment(project,f);Attachments.download(blob,f.name);}catch(error){toast('Orijinal dosya açılamadı: '+error.message);}});project.files.forEach(async(f,i)=>{const blob=await Attachments.get(f.hash).catch(()=>null);if(current!==project)return;const label=document.querySelector(`[data-file-status="${i}"]`);if(label)label.textContent=blob?'Orijinal dosya mevcut':'Orijinal yeniden bağlanmalı';});}
async function checkOriginalFiles(){const project=current,missing=[];for(const f of project.files)try{if(!f.binary)throw new Error('Eski kayıt');await WorkspaceStore.readAttachment(project,f);}catch{missing.push(f.name);}if(current!==project)return false;if(missing.length){$('#workflow-message').textContent='Orijinal dosyalar eksik; yeniden seçin veya kayıt klasörünü bağlayın: '+missing.join(', ');return false;}return true;}
async function downloadProjectPackage(){capture();if(!persist())return;const project=current;$('#package-status').textContent='Dosya paketi hazırlanıyor…';const entries=[{name:'teklif.json',text:JSON.stringify(project,null,2)},{name:'workspace.json',text:JSON.stringify({format:'ls-moldworks-backup',version:1,projects:[project],settings:project.issuer||{},customers:Customers.all().filter(c=>c.id===project.customerId)},null,2)},{name:'talep.txt',text:project.request||''}],manifest=[];
for(const f of project.files){const blob=await WorkspaceStore.readAttachment(project,f);entries.push({name:'ekler/'+Attachments.storedName(f),blob});manifest.push({name:f.name,path:'ekler/'+Attachments.storedName(f),kind:f.kind||fileKind(f.name),hash:f.hash,size:f.size});}
const output=await Attachments.outputGet(project);if(output)entries.push({name:output.approved?'teklif.approved.html':'teklif.draft.html',text:output.html});entries.push({name:'dosya-listesi.json',text:JSON.stringify({files:manifest,outputIncluded:!!output},null,2)});const zip=await ZipPackage.build(entries);Attachments.download(zip,project.code+'-dosya-paketi.zip');if(current===project)$('#package-status').textContent='Paket indirildi: '+manifest.length+' orijinal dosya'+(output?' ve teklif çıktısı.':'. Güncel teklif çıktısı henüz oluşturulmadı.');}
function datesHtml(p){return `<section class="panel body-pad" id="quote-dates"><h3>Teklif ve müşteri dönüş tarihleri</h3><div class="two"><label>Teklif tarihi<input type="date" id="quote-date" required value="${QuoteDates.quoteDate(p)}"></label><label>Müşteriye son dönüş tarihi · isteğe bağlı<input type="date" id="response-due" value="${esc(p.responseDue||'')}"></label></div><p id="valid-until-summary"></p></section>`;}
function updateDateSummary(){if(!current||!$('#valid-until-summary'))return;const p={...current,quoteDate:$('#quote-date').value,terms:{...current.terms,validityDays:document.querySelector('[name="term-validityDays"]').value}};$('#valid-until-summary').textContent='Teklif geçerlilik sonu: '+QuoteDates.format(QuoteDates.validUntil(p))+' · Teklif tarihi + geçerlilik gün sayısı.';}
function dateBadge(p){const c=QuoteDates.classify(p);return `${c.overdue?'<span class="badge status-cancelled">Dönüş gecikti</span>':c.upcoming?'<span class="badge status-pending">Dönüş yaklaşıyor</span>':''}${c.expired?'<span class="badge status-cancelled">Geçerlilik doldu</span>':''}`;}
function dateFiltersHtml(){return `<div class="date-filters">${[['all','Tüm tarihler'],['overdue','Geciken dönüşler'],['upcoming','Yaklaşan dönüşler'],['expired','Geçerliliği dolanlar']].map(([k,t])=>`<button data-date-filter="${k}" class="filter-chip ${dateFilter===k?'selected':''}" aria-pressed="${dateFilter===k}">${t}</button>`).join('')}</div>`;}
function deadlineCards(){return `<div class="deadline-cards">${[['overdue','Geciken dönüşler'],['upcoming','Önümüzdeki 3 gün'],['expired','Geçerliliği dolanlar']].map(([k,t])=>`<button data-date-filter="${k}" aria-pressed="${dateFilter===k}" class="deadline-card ${dateFilter===k?'selected':''}"><span>${t}</span><strong>${projects.filter(p=>QuoteDates.classify(p)[k]).length}</strong></button>`).join('')}</div>`;}
function bindDateFilters(){document.querySelectorAll('[data-date-filter]').forEach(b=>b.onclick=()=>{dateFilter=b.dataset.dateFilter;document.querySelectorAll('[data-date-filter]').forEach(el=>{el.classList.toggle('selected',el.dataset.dateFilter===dateFilter);el.setAttribute('aria-pressed',String(el.dataset.dateFilter===dateFilter));});$('#rows').innerHTML=rows($('#search').value);bindOpen();});}
function bindRepricing(){document.querySelectorAll('.reprice-alternative').forEach(b=>b.onclick=()=>openRepricing(b.dataset.id));}
function openRepricing(id){capture();const project=current,source=project.alternatives.find(a=>a.id===id);if(!source)return;const before=Workflow.content(project),plan=Repricing.create(source,Settings.get());document.querySelector('#repricing-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='repricing-dialog';dialog.className='approval-dialog';const fork=Workflow.approved(project)||project.status==='sent';dialog.innerHTML=`<h2>Güncel fiyatlarla yeni alternatif</h2><p>${fork?'Onaylı teklif korunacak; yeni revizyonda yeni alternatif oluşturulacak.':'Eski alternatif korunacak; yanına güncel fiyatlı alternatif eklenecek.'} Geometri, ölçüler ve yerleşim değişmez. Önceki alternatif yeni çıktıda kapsam dışı kalır.</p><div class="two"><section><h3>Önceki hesap</h3>${CostUI.summaryHtml(source)}</section><section><h3>Güncel hesap</h3>${CostUI.summaryHtml(plan.alternative)}</section></div><div class="notice">Katalogda bulunamayan veya elle belirlenen fiyatlar tahmin edilmez; yeni alternatifte boş bırakılır. Yeni alternatif onay gerektirir.</div><div class="actions"><button id="apply-repricing" class="primary">${fork?'Yeni revizyon ve alternatifi oluştur':'Yeni alternatifi ekle'}</button><button id="cancel-repricing" class="secondary">Vazgeç</button></div><p id="repricing-result" role="status"></p>`;document.body.append(dialog);dialog.showModal();$('#cancel-repricing').onclick=()=>{dialog.close();dialog.remove();};$('#apply-repricing').onclick=()=>{if(current!==project||Workflow.content(project)!==before){$('#repricing-result').textContent='Teklif değişti. Yeniden karşılaştırın.';return;}let target=project;if(fork){if(!persist())return;target=structuredClone(project);target.id=crypto.randomUUID();target.revision=Math.max(...projects.filter(p=>p.base===project.base).map(p=>p.revision||0))+1;target.code=target.base+'_rev'+target.revision;target.created=target.updatedAt=new Date().toISOString();target.quoteDate=QuoteDates.today();Workflow.invalidate(target);projects.push(target);}else markEdited();const old=target.alternatives.find(a=>a.id===source.id);const wasIncluded=old.offerIncluded;old.offerIncluded=false;target.alternatives.push(plan.alternative);if(!persist()){target.alternatives.pop();if(wasIncluded===undefined)delete old.offerIncluded;else old.offerIncluded=wasIncluded;if(fork)projects.pop();return;}dialog.close();dialog.remove();openProject(target.id);toast('Güncel fiyat alternatifi oluşturuldu. Eski hesap korundu.');};dialog.addEventListener('cancel',()=>dialog.remove());}

async function parseBackupFile(file){if(/\.zip$/i.test(file.name)){const entries=await ZipPackage.read(file),workspace=entries.get('workspace.json');if(!workspace)throw new Error('Paket workspace.json içermiyor.');if(workspace.size>20*1024*1024)throw new Error('Paketin arşiv kaydı 20 MB sınırını aşıyor.');const data=QuoteTools.validateBackup(JSON.parse(await workspace.text()));let restored=0;for(const p of data.projects)for(const f of p.files)if(f.binary){const blob=entries.get('ekler/'+Attachments.storedName(f));if(!blob||blob.size!==f.size)throw new Error(f.name+': paket içindeki orijinal dosya eksik.');await Attachments.put(f.hash,blob);restored++;}data.fileRestoreSummary={restored,missing:0};return data;}if(file.size>20*1024*1024)throw new Error('JSON dosyası 20 MB sınırını aşıyor.');return QuoteTools.validateBackup(JSON.parse(await file.text()));}

function quotePartImage(p){return /^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(p.thumbnail||'')?`<img class="quote-part-image" src="${p.thumbnail}" alt="${esc(p.part)} görünüşü">`:'';}
function bindTechnicalButtons(){document.querySelectorAll('.technical-open').forEach(b=>b.onclick=async()=>{if(!window.TechnicalView){toast('3D bileşeni yükleniyor; biraz sonra yeniden deneyin.');return;}capture();const project=current,a=project.alternatives.find(a=>a.id===b.dataset.id);await window.TechnicalView.open({project,alternative:a,readFile:f=>WorkspaceStore.readAttachment(project,f),apply:patch=>{if(current!==project)throw new Error('Proje değişti. Yeniden açın.');capture();markEdited();const old=structuredClone(a);Object.assign(a,patch);if(!persist()){Object.keys(a).forEach(k=>delete a[k]);Object.assign(a,old);throw new Error('Taslak kaydedilemedi.');}openProject(project.id);toast('Teknik taslak ve malzeme hesabı güncellendi.');},thumbnail:image=>{if(current!==project)return;markEdited();project.thumbnail=image;if(persist())$('#thumbnail-current').innerHTML=thumbnail(project);}});});}
function bindDocumentIntake(){const box=$('#document-intake');if(!box||!current)return;box.oninput=e=>e.stopPropagation();const project=current,documents=project.files.filter(f=>/\.(pdf|eml|txt|dxf|png|jpe?g|webp)$/i.test(f.name));box.innerHTML=`<div class="document-intake"><h3>Belgeden talep ve 2D ölçü analizi</h3><p>Dosyaları ayrı ayrı inceleyin. Farklı projelere ait belgeleri birlikte uygulamayın.</p><label>Kaynak belge<select id="intake-source"><option value="">Yapıştırılmış müşteri talebi</option>${documents.map(f=>`<option value="${esc(f.hash)}">${esc(f.name)}</option>`).join('')}</select></label><button type="button" class="secondary" id="intake-analyze">Seçili kaynağı analiz et</button><p id="intake-status" role="status"></p><div id="intake-review"></div></div>`;$('#intake-analyze').onclick=async()=>{const hash=$('#intake-source').value,file=documents.find(f=>f.hash===hash),button=$('#intake-analyze');button.disabled=true;$('#intake-status').textContent='Belge okunuyor; görüntülerde OCR uygulanıyor…';try{const blob=file?await WorkspaceStore.readAttachment(project,file):new Blob([$('#request').value],{type:'text/plain'});if(!file&&!$('#request').value.trim())throw new Error('Müşteri talebini yapıştırın veya belge seçin.');const name=file?.name||'talep.txt',response=await fetch('/api/documents?filename='+encodeURIComponent(name),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:blob}),result=await response.json();if(!response.ok)throw new Error(result.error);if(current!==project)return;renderDocumentReview(project,file,result);}catch(error){if(current===project)$('#intake-status').textContent=error.message;}finally{if(current===project)button.disabled=false;}};}
function renderDocumentReview(project,file,result){const findings=result.findings,labels={cavities:'Göz sayısı',arrangement:'Düzen',core:'Maça',slide:'Kızak',trim:'Trim',dimensions:'Parça ölçüsü',alloy:'Alaşım talebi',press:'Pres tonajı'},display=f=>f.kind==='dimensions'?f.value.join(' × ')+' mm':f.kind==='arrangement'?'1+1 sağ / sol':f.value==='none'?'Yok':typeof f.value==='boolean'?(f.value?'Dahil':'Hariç'):f.value;$('#intake-status').textContent='Analiz tamamlandı. Kaynakla karşılaştırıp uygulanacak bilgileri seçin.';$('#intake-review').innerHTML=`<h4>${esc(file?.name||'Yapıştırılan talep')}</h4>${findings.map((f,i)=>`<label class="finding"><input type="checkbox" data-finding="${i}" ${f.kind==='dimensions'?'disabled':''}><span>${esc(labels[f.kind])}: <strong>${esc(display(f))}</strong><small>Sayfa ${f.page} · ${esc(f.method)} · “${esc(f.evidence)}”</small></span></label>`).join('')||'<p>Belirgin talep veya üçlü ölçü bulunamadı. Çıkarılan metni inceleyin; 2D ölçülerini aşağıda girebilirsiniz.</p>'}<button type="button" class="secondary" id="intake-apply">Seçili talep bilgilerini uygula</button><details><summary>Okunan belge metni</summary><pre class="document-text">${esc(result.pages.map(p=>'Sayfa '+p.page+'\n'+p.text).join('\n\n'))}</pre></details><h4>Yalnız 2D’den malzeme ön hesabı</h4><p>Parçanın en, boy ve yüksekliğini doğrulayın. Görünüş, birim ve ölçeği kontrol edin. Çizim sayfasının boyutu parça boyutu değildir.</p><label>Bulunan ölçü grubu<select id="drawing-dimensions"><option value="">Ölçü grubunu seçin / elle girin</option>${findings.filter(f=>f.kind==='dimensions').map(f=>`<option value="${f.value.join(',')}">${f.value.join(' × ')} mm · sayfa ${f.page}</option>`).join('')}</select></label><div class="two">${['X','Y','Z'].map(k=>`<label>Parça ${k} · mm<input type="number" min="0.001" max="100000" step="any" data-drawing-dim="${k}"></label>`).join('')}</div><label>Uygulanacak alternatif<select id="drawing-target"><option value="all">Tüm mevcut alternatifler</option>${project.alternatives.map(a=>`<option value="${a.id}">${a.cavities} göz · ${esc(a.label||a.id.slice(0,6))}</option>`).join('')}</select></label><label class="toggle">Bu belge aynı parçaya ait; ölçüleri mm olarak doğruladım<input type="checkbox" id="drawing-confirm"></label><button type="button" class="secondary" id="drawing-apply">2D ölçüleriyle ön hesabı oluştur</button><p>${result.notes.map(esc).join('<br>')}</p>`;
$('#intake-apply').onclick=()=>{const chosen=[...document.querySelectorAll('[data-finding]:checked')].map(i=>findings[Number(i.dataset.finding)]);if(!chosen.length){toast('Uygulanacak bilgileri seçin.');return;}for(const kind of ['core','slide','trim','arrangement'])if(new Set(chosen.filter(f=>f.kind===kind).map(f=>f.value)).size>1){toast('Çelişen bilgiler var; birini seçin.');return;}capture();markEdited();const requested=[...new Set(chosen.filter(f=>f.kind==='cavities').map(f=>f.value))];for(const count of requested)if(!project.alternatives.some(a=>a.cavities===count))project.alternatives.push(alternative(count));const targets=project.alternatives.filter(a=>!requested.length||requested.includes(a.cavities));for(const a of targets){for(const f of chosen){if(['core','slide'].includes(f.kind))a[f.kind]=f.value;if(['alloy','press'].includes(f.kind))a['requested'+f.kind[0].toUpperCase()+f.kind.slice(1)]=f.value;if(f.kind==='trim')a.pricing={...a.pricing,trimEnabled:f.value};if(f.kind==='arrangement'&&a.cavities%2===0){a.requestedArrangement=f.value;if(a.technical)a.technical.arrangement=f.value;}}}project.analysis=(project.analysis||'')+'\nOnaylanan müşteri talebi ('+(file?.name||'yapıştırılan metin')+'): '+chosen.map(f=>labels[f.kind]+': '+display(f)).join('; ');if(persist()){openProject(project.id);toast('Seçili bilgiler uygulandı. Alternatiflerin kapsamını inceleyin.');}};
$('#drawing-dimensions').onchange=e=>{if(!e.target.value)return;e.target.value.split(',').forEach((v,i)=>document.querySelector(`[data-drawing-dim="${'XYZ'[i]}"]`).value=v);};$('#drawing-apply').onclick=()=>{const sizes=[...document.querySelectorAll('[data-drawing-dim]')].map(i=>Number(i.value));if(!$('#drawing-confirm').checked||sizes.some(v=>!Number.isFinite(v)||v<=0||v>100000)){toast('Üç ölçüyü ve belge onayını tamamlayın.');return;}const target=$('#drawing-target').value;capture();markEdited();for(const a of project.alternatives.filter(a=>target==='all'||a.id===target)){const mesh={version:'step-mesh-v1',units:'mm',min:[0,0,0],max:sizes,positions:[0,0,0,sizes[0],0,0,0,sizes[1],sizes[2]],triangles:[0,1,2],faceIds:[0],faces:[{id:0}],suggestions:{recommendedAxis:'Z'}},state=MoldPlan.initial(mesh,{...a,technical:undefined});state.sideMode=true;const patch=MoldPlan.patch(mesh,state,a).patch;delete patch.technical;delete patch.core;delete patch.coreSize;patch.costLines.push(...(a.costLines||[]).filter(l=>l.technicalGenerated&&l.category==='core'));delete a.technical;Object.assign(a,patch);a.drawingBasis={sourceHash:file?.hash||'',sourceName:file?.name||'Yapıştırılan metin',dimensions:sizes,confirmedAt:new Date().toISOString()};}project.analysis=(project.analysis||'')+'\n2D temelli ön hesap: '+sizes.join(' × ')+' mm; kaynak: '+(file?.name||'Yapıştırılan metin')+'. Maça ihtiyacı 2D üzerinden doğrulanmadı.';if(persist()){openProject(project.id);toast('2D ölçüleriyle blok ön hesabı hazırlandı; çelik ve maça kapsamını inceleyin.');}};}
